      background: var(--surface);
      border: 1px solid #d6deeb;
      border-radius: 2rem;
      box-shadow: var(--shadow);
    }

    .hero-panel {
      padding: clamp(1.5rem, 5vw, 3.5rem);
      color: #ffffff;
      background:
        linear-gradient(155deg, #11245a 0%, #2457d6 58%, #5c7cff 100%);
    }

    .eyebrow {
      margin: 0 0 1rem;
      font-size: 0.85rem;
      font-weight: 800;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    h1 {
      max-width: 11ch;
      margin: 0;
      font-size: clamp(2.25rem, 7vw, 4.6rem);
      line-height: 0.95;
      letter-spacing: -0.075em;
    }

    .hero-copy {
      max-width: 32rem;
      margin: 1.5rem 0 0;
      color: #eef4ff;
      font-size: 1.08rem;
