    .form-panel {
      padding: clamp(1.5rem, 5vw, 3.5rem);
    }

    .form-intro {
      margin: 0 0 1.6rem;
      color: var(--text-muted);
    }

    .contact-form {
      display: grid;
      gap: 1rem;
    }

    .form-field {
      display: grid;
      gap: 0.45rem;
    }

    label {
      font-weight: 750;
      color: var(--text);
    }

    .required-note,
    .optional-note {
      font-weight: 650;
      color: var(--text-muted);
    }

    input {
      width: 100%;
      min-height: 3.15rem;
      padding: 0.85rem 0.95rem;
      color: var(--text);
      background: #ffffff;
      border: 1.5px solid var(--border);
      border-radius: 0.9rem;
      font: inherit;
      transition: border-color 160ms ease, box-shadow 160ms ease, background-color 160ms ease;
    }

    input:hover {
      border-color: var(--border-strong);
    }

    input:focus {
      border-color: var(--primary);
      outline: 3px solid transparent;
      box-shadow: 0 0 0 4px var(--focus);
    }

    input[aria-invalid="true"] {
      background: var(--danger-bg);
      border-color: var(--danger);
    }

    .helper-text {
      margin: 0;
      color: var(--text-muted);
      font-size: 0.95rem;
    }

    .error-message {
      display: none;
      margin: 0;
      color: var(--danger);
      font-size: 0.95rem;
      font-weight: 700;
    }

    .error-message.is-visible {
      display: block;
    }

    .form-status {
      min-height: 1.5rem;
      margin: 0;
      color: var(--success);
      font-weight: 750;
    }

    .button-row {
      display: flex;
      align-items: center;
      gap: 1rem;
      margin-top: 0.5rem;
      flex-wrap: wrap;
    }

    button {
      min-height: 3.15rem;
      padding: 0.9rem 1.35rem;
      color: #ffffff;
      background: var(--primary);
      border: 2px solid var(--primary);
      border-radius: 999px;
      cursor: pointer;
      font: inherit;
      font-weight: 800;
      transition: background-color 160ms ease, border-color 160ms ease, transform 160ms ease;
    }

    button:hover {
      background: var(--primary-hover);
      border-color: var(--primary-hover);
    }

    button:focus {
      outline: 3px solid transparent;
      box-shadow: 0 0 0 4px var(--focus);
    }

    button:active {
      transform: translateY(1px);
    }

    .privacy-note {
      margin: 0;
      color: var(--text-muted);
      font-size: 0.95rem;
    }

    @media (max-width: 760px) {
      .support-layout {
        grid-template-columns: 1fr;
        border-radius: 1.25rem;
      }

      .hero-panel,
