</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <div id="app"></div>

  <script>
    const fields = [
      {
        id: "full-name",
        name: "fullName",
        label: "Full name",
        type: "text",
        autocomplete: "name",
        required: true,
        placeholder: "Alex Morgan",
        requiredMessage: "Enter your full name."
      },
      {
        id: "email",
        name: "email",
        label: "Email address",
        type: "email",
        autocomplete: "email",
        required: true,
        placeholder: "alex@example.com",
        requiredMessage: "Enter your email address.",
        formatMessage: "Enter an email address in the format name@example.com.",
        pattern: /^[^\s@]+@[^\s@]+\.[^\s@]+$/
      },
      {
        id: "phone",
        name: "phone",
        label: "Phone number",
        type: "tel",
        autocomplete: "tel",
        required: false,
        placeholder: "+1 555 123 4567",
        helper: "Optional. Use digits with spaces, dashes, or parentheses, such as +1 555 123 4567.",
        formatMessage: "Enter a phone number using digits, spaces, dashes, parentheses, and an optional leading plus sign.",
        minDigits: 7,
        pattern: /^\+?[0-9\s().-]{7,20}$/
      }
    ];

    const Header = () => `
      <header class="site-header">
        <div class="brand" aria-label="Acme Support">
          <span class="brand-mark" aria-hidden="true">A</span>
          <span>Acme Support</span>
        </div>
      </header>
    `;

    const HeroPanel = () => `
      <section class="hero-panel" aria-labelledby="support-title">
        <p class="eyebrow">Support desk</p>
        <h1 id="support-title">How can we help?</h1>
        <p class="hero-copy">Tell us a little about yourself and our product support team will route your request to the right specialist.</p>
        <div class="response-card">
          <strong>Typical response time</strong>
          <p>Most support requests receive a reply within one business day.</p>
        </div>
      </section>
    `;

    const FormField = (field) => {
      const helperId = field.helper ? `${field.id}-helper` : "";
      const errorId = `${field.id}-error`;
      const describedBy = [helperId, errorId].filter(Boolean).join(" ");
      const requiredLabel = field.required
        ? '<span class="required-note" aria-hidden="true">*</span><span class="sr-only"> required</span>'
        : '<span class="optional-note">(optional)</span>';

      return `
        <div class="form-field">
          <label for="${field.id}">${field.label} ${requiredLabel}</label>
          <input
            id="${field.id}"
            name="${field.name}"
            type="${field.type}"
            autocomplete="${field.autocomplete}"
            placeholder="${field.placeholder}"
            ${field.required ? "required" : ""}
            aria-invalid="false"
            aria-describedby="${describedBy}"
          >
          ${field.helper ? `<p class="helper-text" id="${helperId}">${field.helper}</p>` : ""}
          <p class="error-message" id="${errorId}" aria-live="polite"></p>
        </div>
      `;
    };

    const ContactForm = () => `
      <section class="form-panel" aria-labelledby="form-title">
        <h2 id="form-title">Contact support</h2>
        <p class="form-intro">Fields marked with <span aria-hidden="true">*</span> are required.</p>
        <form class="contact-form" id="support-form" novalidate>
          ${fields.map(FormField).join("")}
          <div class="button-row">
            <button type="submit">Submit request</button>
            <p class="privacy-note">We will only use these details to respond to your request.</p>
          </div>
          <p class="form-status" id="form-status" aria-live="polite"></p>
        </form>
      </section>
    `;

    const App = () => `
      ${Header()}
      <main id="main-content">
        <div class="support-layout">
          ${HeroPanel()}
          ${ContactForm()}
        </div>
      </main>
    `;

    document.getElementById("app").innerHTML = App();

    const form = document.getElementById("support-form");
    const statusMessage = document.getElementById("form-status");

    const getFieldConfig = (input) => fields.find((field) => field.id === input.id);

    const setError = (input, message) => {
      const error = document.getElementById(`${input.id}-error`);
      input.setAttribute("aria-invalid", message ? "true" : "false");
      error.textContent = message;
      error.classList.toggle("is-visible", Boolean(message));
    };

    const validateInput = (input) => {
      const field = getFieldConfig(input);
      const value = input.value.trim();

      if (field.required && value.length === 0) {
        setError(input, field.requiredMessage);
        return false;
      }

      if (value.length > 0 && field.pattern && !field.pattern.test(value)) {
        setError(input, field.formatMessage);
        return false;
      }

      if (value.length > 0 && field.minDigits && value.replace(/\D/g, "").length < field.minDigits) {
        setError(input, field.formatMessage);
        return false;
      }

      setError(input, "");
      return true;
    };

    form.addEventListener("input", (event) => {
      if (event.target.matches("input")) {
        validateInput(event.target);
        statusMessage.textContent = "";
      }
    });

    form.addEventListener("blur", (event) => {
      if (event.target.matches("input")) {
        validateInput(event.target);
      }
    }, true);

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      const inputs = Array.from(form.querySelectorAll("input"));
      const firstInvalid = inputs.find((input) => !validateInput(input));

      if (firstInvalid) {
        statusMessage.textContent = "Please fix the highlighted fields before submitting.";
        firstInvalid.focus();
        return;
      }

      form.reset();
      inputs.forEach((input) => setError(input, ""));
      statusMessage.textContent = "Thanks. Your support request is ready to send.";
    });
  </script>
</body>
</html>
