cd /workspace/sandbox/variants/accessible_basic/simple-contact-form--framework-react--style-modern--validation-message-present/gpt-5.5__s2
awk '/<script>/{flag=1;next}/<\/script>/{flag=0}flag' index.html > /tmp/contact-form-script.js
node --check /tmp/contact-form-script.js
node <<'NODE'
const fs = require('fs');
const vm = require('vm');
const html = fs.readFileSync('index.html', 'utf8');
const script = html.match(/<script>([\s\S]*)<\/script>/)[1];
const appNode = { innerHTML: '' };
const formNode = { addEventListener() {}, querySelectorAll() { return []; }, reset() {} };
const statusNode = { textContent: '' };
const errorNode = { textContent: '', classList: { toggle() {} } };
const context = {
  document: {
    getElementById(id) {
      if (id === 'app') return appNode;
      if (id === 'support-form') return formNode;
      if (id === 'form-status') return statusNode;
      if (id.endsWith('-error')) return errorNode;
      return null;
    }
  }
};
vm.runInNewContext(script, context);
const rendered = appNode.innerHTML;
const checks = [
  ['three form-field wrappers', (rendered.match(/class="form-field"/g) || []).length === 3],
  ['full name input rendered', rendered.includes('id="full-name"') && rendered.includes('required')],
  ['email input rendered', rendered.includes('id="email"') && rendered.includes('type="email"')],
  ['phone helper rendered', rendered.includes('id="phone-helper"') && rendered.includes('Optional. Use digits')],
  ['submit button rendered', rendered.includes('<button type="submit">Submit request</button>')],
  ['single main landmark', (rendered.match(/<main\b/g) || []).length === 1],
  ['single h1', (rendered.match(/<h1\b/g) || []).length === 1]
];
const failed = checks.filter(([, ok]) => !ok).map(([name]) => name);
if (failed.length) {
  console.error('Failed checks: ' + failed.join(', '));
  process.exit(1);
}
console.log(checks.map(([name]) => `ok: ${name}`).join('\n'));
